import { Component, OnInit, Input } from '@angular/core';

// View Controller
import { lRouteKey } from './login.routes';
import { ActivatedRoute } from '@angular/router';

@Component({
  selector: 'user-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})

export class LoginComponent implements OnInit {
  //customizability
  @Input() fullKit: boolean = true;
  @Input() logoBox: boolean = false;
  @Input() error: boolean = false;
  @Input() background: boolean = false;
  @Input() footer: boolean = false;

  routeKey = lRouteKey;
  routeView = this.route.snapshot.url[0] ? this.route.snapshot.url[0]['path'] : ''; // controls view of the page

  constructor(private route: ActivatedRoute) {
  }
  selectedTab = this.routeKey.login.path; // for switch button
  ngOnInit(): void {
    if (this.routeView == this.routeKey.createAccount.path) {
      this.selectedTab = this.routeView;
    }
  }
}
