import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Router } from '@angular/router';
import { DataInterface } from '../../Functions_API';

@Injectable({
    providedIn: 'root'
})


export class ErrorHandlingService  {

    private _error$ = new BehaviorSubject<{Success: boolean, Message: string, Token?: any
    } | null>(null);
    error$: Observable<DataInterface | null> = this._error$.asObservable();

    setError(ErrorData: DataInterface) {
        if(ErrorData.Message !== null) {
            this._error$.next(ErrorData);
        }
        return ErrorData;
    }

    clearError() {
        this._error$.next(null);
    }

}