import { Component } from '@angular/core';
//import loggedIn capability
import { IndexedDBService } from '../../../Functions_USession';
//import dynamic tracking for refresh
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import {lRouteKey} from '../login.routes';


@Component({
  selector: 'login-button',
  templateUrl: `./loginButton.component.html`,
  styleUrls: ['./loginButton.component.scss']
})
export class LoginButtonComponent {
  isLoggedIn!: boolean;
  //routing
  view = lRouteKey;

  constructor(
    private router: Router,
    private indexedDBService: IndexedDBService
  ) {
    this.router.events.pipe(
      filter(event => event instanceof NavigationEnd)
    ).subscribe(() => {
      this.indexedDBService.isLoggedIn().then(isLoggedIn => {
        this.isLoggedIn = isLoggedIn;
      });
    });


  }
  logIn() {
    this.router.navigate(['/'+this.view.login]);
  }
  settings() {
    this.router.navigate(['/'+this.view.login]);
  }
}
