import { Component, Input} from '@angular/core';
import { EC_Functions } from '../EC_Functions';
import { take } from 'rxjs';
import { IndexedDBService } from '../../Functions_USession';

@Component({
  selector: 'app-tick-marker',
  templateUrl: './tick-marker.component.html',
  styleUrls: ['./tick-marker.component.scss']
})


export class TickMarkerComponent {
  //input the id of item having the tick marker
  @Input() id: any;
  hide:boolean = false;
  CustomPackages: any;

  constructor(private EC_Func: EC_Functions,private userService: IndexedDBService) {
    this.Cart = this.EC_Func.getCartt();
  }
  // Vars
  Cart: any[];
    ngOnInit(): void {
      // Update Cart and Associated Vars 
      this.EC_Func.Cart.subscribe(items => {
        this.Cart = items;
      });
      this.userService.USERDATA$.pipe(take(1)).subscribe((data: any) => {
                this.CustomPackages = data.SETTINGS.Packages;
              })
            
      if(this.CustomPackages) {
        this.hide = true;
      }
    }

  //update cart given the the item in cart that matches ID and operator
  updateQuantity(id: any, delta: (number | string)): void {
  if (typeof(delta) === "string"){
    if (delta === "+"){
      this.EC_Func.UpdateCart(this.Cart[id], "add");
    } else {
      this.EC_Func.UpdateCart(this.Cart[id], "sub");
    }
  } else{
    this.EC_Func.UpdateCart(this.Cart[id], "set", delta);
  }
  
  }
  getQuantity(id: any): number {
    return this.Cart[id].Quantity ?? 0
  }
  //get value from input, parse to num and call updatequantity with it
  updateC(id: any, event: Event) {
    const inputElement = event.target as HTMLInputElement | null;
    if (inputElement && inputElement.value !== null) {
      const value = inputElement.value;
      const numericValue = parseFloat(value);
      if (!isNaN(numericValue)) {
        this.updateQuantity(id, numericValue);
      }
      inputElement.value = '';
    }
  }
}


