import { Component } from '@angular/core';
import { EC_Functions } from '../EC_Functions';
import { PackagesInterface } from '../EC_Packages';
import { ServicesInterface } from '../EC_Services';


@Component({
  selector: 'app-cart',
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.scss']
})
export class CartComponent {
  constructor(private EC_Func: EC_Functions) {
    this.Cart = this.EC_Func.getCartt();
    this.Total = this.EC_Func.getcartTotal(this.Cart);
  }

  // Vars
  Total: number = 0;
  Cart: any[];
  ngOnInit(): void {
    // Update Cart and Associated Vars 
    this.EC_Func.Cart.subscribe(items => {
      this.Cart = items;
      this.Total = this.EC_Func.getcartTotal(this.Cart);
    });
  }

  // Functions 

  Remove(item: (PackagesInterface | ServicesInterface)) {
    this.EC_Func.UpdateCart(item, "clear");
  }


  trackByFn(index: number, item: any): number {
    return item.ID; // or any unique property of the item
  }


}
