import { Component, Input, OnInit } from '@angular/core';
import { EC_Functions } from '../EC_Functions';
import { eRouteKey } from '../ecommerce.routes';
import { Router } from '@angular/router';
import { checkmark } from 'ionicons/icons';

@Component({
  selector: 'ec-product-tier',
  templateUrl: './product-tier.component.html',
  styleUrls: ['./product-tier.component.scss']
})
export class ProductTierComponent implements OnInit {
  //view
  view = eRouteKey;

  // Input For Tiers
  @Input() Product: any;
  @Input() CustomPackages: any;
  checkmark: string = checkmark;

  constructor(private EC_Func: EC_Functions, private router: Router) {
  }
  // Vars
  ProductTiers: any;
  ProductInclusions: string[] = [];
  ngOnInit(): void {
    this.ProductTiers = this.Product.Tiers;
    this.ProductInclusions = this.Product.Inclusions;
    //console.log(this.ProductTiers); // for testing purposes
  }
  onClick(index: number) {
    if (this.CustomPackages) {
      this.EC_Func.UpdateCart(this.Product, "add", index);
      this.router.navigate(['/' + this.view.checkout.path]);
    } else {
      this.EC_Func.UpdateCart(this.Product, "add", index);
      this.router.navigate(['/' + this.view.ecommerce.path]);
    }
  }

  Convert = this.EC_Func.ConvertCurrency;

}
