import { Component, Input, OnDestroy, OnInit } from '@angular/core';
//import background from pre-determined path
import { IndexedDBService } from '../../Functions_USession';

@Component({
  selector: 'background',
  templateUrl: './main-background.component.html',
  styleUrls: ['./main-background.component.scss']
})
export class BackgroundComponent implements OnInit, OnDestroy {
  @Input() BackgroundImage!: string;
  PhotoOnly: boolean = true;
  userSubscription: any;
  
  constructor(
    private userService: IndexedDBService
  ) {}

  ngOnInit(): void {
    if(!this.BackgroundImage) {
      this.userSubscription = this.userService.USERDATA$.subscribe(
        (userData) => {
          let SettingCheck = userData ? userData.CONFIG : null;
          if(SettingCheck){
            this.BackgroundImage = userData.CONFIG.BackgroundImage;  
          }
        }
      );
    }
  }

  ngOnDestroy() {
    // Unsubscribe to prevent memory leaks
    if (this.userSubscription) {
      this.userSubscription.unsubscribe();
    }
  }
}
