import { Component, Input } from '@angular/core';

// User View
import { Router } from '@angular/router';
import { IndexedDBService } from '../../Functions_USession';

@Component({
  selector: 'logo-box',
  templateUrl: './logo-box.component.html',
  styleUrls: ['./logo-box.component.scss']
})
export class LogoBoxComponent {

  @Input() styling?: string;
  @Input() Boxstyling?: string;
  @Input() AltText!: string;
  @Input() Logo!: string; 
  @Input() TagOn: boolean = false; 
  Tag!: string;
  userSubscription: any;

  constructor(private userService: IndexedDBService, private View: Router) {
      
  }

  ngOnInit() {
    this.userSubscription = this.userService.USERDATA$.subscribe(
      (userData) => {
        let SettingCheck = userData ? userData.CONFIG : null;
        if(SettingCheck){
          this.Logo = this.Logo ?? userData.CONFIG.LOGO;  
          this.AltText = this.AltText ?? userData.CONFIG.BUSName + ' Logo - ' + userData.CONFIG.BUSTag;
          this.Tag = userData.CONFIG.BUSTag;
        }
      }
    );
  }
  
  ngOnDestroy() {
    // Unsubscribe to prevent memory leaks
    if (this.userSubscription) {
      this.userSubscription.unsubscribe();
    }
  }
  
  changeView(view: string): void {
    this.View.navigate(['/'+view]);
  }
  
}
