import { Component, Input, OnInit, OnChanges, SimpleChanges } from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { videocamOff } from 'ionicons/icons';
import { FormService } from '../../Functions_Forms';
import { IndexedDBService } from '../../Functions_USession';
import { take } from 'rxjs';

@Component({
  selector: 'app-videodisplay',
  templateUrl: './videodisplay.component.html',
  styleUrls: ['./videodisplay.component.scss']
})
export class VideodisplayComponent implements OnInit, OnChanges {
  @Input() videoLink: string = '';
  @Input() autoplay: boolean = false;
  VideoSrc: 'External' | 'Internal' = 'External';
  Domain!: string;
  safeVideoLink!: SafeResourceUrl;

  constructor(
    private sanitizer: DomSanitizer,
    private formService: FormService,
    private userService: IndexedDBService
  ) {  }

  VideoIcon = videocamOff;

  ngOnInit(): void {
    // Ensure Domain is set 
    this.userService.USERDATA$.pipe(take(1)).subscribe((userData: any) => {
      this.Domain = userData.CONFIG.URL;
      if (!this.videoLink) {
        // use take and susbcribe to getuserService user data 
        this.userService.USERDATA$.pipe(take(1)).subscribe((userData: any) => {
            this.videoLink = userData?.video ?? userData?.videoR ?? userData?.videoH;
            if(this.videoLink){
              this.safeVideoLink = this.filterVideoLink(this.videoLink);
            }
          }
        );
      } else {
        this.safeVideoLink = this.filterVideoLink(this.videoLink);
      }
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['videoLink']) {
      this.safeVideoLink = this.filterVideoLink(this.videoLink);
    }
  }

  filterVideoLink(url: string): SafeResourceUrl {
    this.VideoSrc = !url.includes(this.Domain) ? 'External' : 'Internal';
    const sanitizedUrl = url.includes('youtube') || url.includes('youtu.be')
      ? this.formService.getYouTubeEmbedUrl_Library(url)
      : url;
    return this.sanitizer.bypassSecurityTrustResourceUrl(sanitizedUrl);
  }
}