import { Component, Input, OnInit, OnChanges, SimpleChanges, ChangeDetectorRef } from '@angular/core';
import { FormGroup } from '@angular/forms';
import { FormService } from '../../../Functions_Forms';
import { SafeResourceUrl, DomSanitizer } from '@angular/platform-browser';

export interface InputConstructor {
  Title: string;
  Name: string;
  Type: string;
  Vars: any;
  Style: string;
  Category: string;
  Placeholder?: string;
  Span?: string;
}

@Component({
  selector: 'form-creator',
  templateUrl: './form-creator.component.html',
  styleUrls: ['./form-creator.component.scss']
})
export class FormCreatorComponent implements OnInit, OnChanges {
  @Input() InputItem: InputConstructor = {
    Title: 'First Name',
    Name: 'firstname',
    Type: 'text',
    Vars: '',
    Style: '',
    Category: 'Test',
    Placeholder: ''
  };
  @Input() formGroup!: FormGroup;
  @Input() labelStyle: string = '';

  videoLink: string = '';
  showVideo: boolean = true;

  constructor(
    private cdr: ChangeDetectorRef,
    private formService: FormService,
  ) { }

  ngOnInit() {
    this.updateVideoLink(this.InputItem.Placeholder ?? '');
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['InputItem'] && !changes['InputItem'].firstChange) {
      this.updateVideoLink(this.InputItem.Placeholder ?? '');
    }
  }

  updateVideoLink(url: string) {
    this.videoLink = url;
    this.showVideo = false;
    this.cdr.detectChanges();
    setTimeout(() => {
      this.showVideo = true;
      this.cdr.detectChanges();
    }, 0);
  }

  onInputChange(event: Event) {
    const inputElement = event.target as HTMLInputElement;
    this.updateVideoLink(inputElement.value);
  }

  isInvalid(entry: any) {
    return this.formService.isInvalid(entry);
  }
}