import { Injectable, Input } from '@angular/core';
import { ErrorHandlingService } from '../../Components/Error/ErrorHandling_Service';
import { IndexedDBService } from '../../Functions_USession';

@Injectable({
  providedIn: 'root'
})
export class ShareprofileService {

  //@Input() 
  User: any;
  Url!: string;
  constructor( private ErrorHelper: ErrorHandlingService, private USessionData: IndexedDBService) {
    if (!this.User) {
      this.USessionData.USERDATA$.subscribe((data: any) => {
        this.User = data;
        this.Url = data.CONFIG.URL;
      });
    }
  }

  public share_(dis_name = this.User.dis_name) {
    let link = this.Url + '/profile/' + dis_name;
    navigator.clipboard.writeText(link);
    this.ErrorHelper.setError({ Success: true, Message: 'Profile share link copied to clipboard! ' });
  }
}
