import { Component, Input } from '@angular/core';

// Api Call
import { KeysComponent } from '../../../KEYS';

// Form Functions
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { FormService } from '../../../Functions_Forms';

// Change View
import { lRouteKey } from '../login.routes';
import { Router } from '@angular/router';

// ION VARS
import { eyeOutline, eyeOffOutline, keyOutline } from 'ionicons/icons';
import { IndexedDBService } from '../../../Functions_USession';
import { take } from 'rxjs/operators';

@Component({
  selector: 'login-newpassform',
  templateUrl: './newpassform.component.html',
  styleUrls: ['./newpassform.component.scss']
})

export class NewPassFormComponent {
  // Vars
  @Input() Pass: string = '';
  // icon
  eye_off_outline = eyeOffOutline;
  eye_outline = eyeOutline;
  key_outline = keyOutline;

  //view
  view = lRouteKey;

  // Login Constructor
  NewPassform: FormGroup;
  constructor(
    private formBuilder: FormBuilder,
    private Keys: KeysComponent,
    public FormService: FormService,
    private router: Router,
    public userService: IndexedDBService
  ) {
    this.NewPassform = this.formBuilder.group({
      website: [''], // honeypot
      passre: ['', [Validators.required, this.FormService.ValidatePassword]],
      passre2: ['', [Validators.required, this.FormService.ValidatePassword]],
    },
      { validator: this.FormService.CheckPassword });
  }

  User!: any;
  ngOnInit(): void {
    this.userService.USERDATA$.pipe(take(1)).subscribe((data: any) => {
      this.User = data;
    })
  }
  
  // Submit Form
  onSubmit(): void {
    // Set Params intop submit form 
    let urlParams = new URLSearchParams(window.location.search);
    let urlParamsSent: { [key: string]: string | null } = {};
    urlParams.forEach((value, key) => {
      urlParamsSent[key] = value;
    });
    // add urlParamsSent to NewPassform value
    for (const key in urlParamsSent) {
      this.NewPassform.addControl(key, this.formBuilder.control(urlParamsSent[key]));
    }
    this.FormService.onSubmit(this.NewPassform, this.User.CALL.Pass_Reset_NewPass);
  }

  requestPassLink() {
    this.router.navigate(["/" + this.view.forgotPassword]);
  }

  // Password show feature 
  ShowPassword = false;
  togglePasswordVisibility() {
    this.ShowPassword = !this.ShowPassword;
  }
  ShowPassword2 = false;
  togglePasswordVisibility2() {
    this.ShowPassword2 = !this.ShowPassword2;
  }
}


