import { Component } from '@angular/core';
import { AccessRestrictOverlayService, Controller } from './overlay.service'

@Component({
  selector: 'access-restrict',
  templateUrl: './access-restrict.component.html',
  styleUrls: ['./access-restrict.component.scss']
})
export class AccessRestrictComponent {
  constructor(private overlayService: AccessRestrictOverlayService) { }
  isVisible = this.overlayService.isVisible$;
  Controller = this.overlayService.Controller$;

  title!: string;
  message!: string;
  buttonTitle!: string;
  buttonAction!: string;

  ngOnInit() {
    // Subscribe to Restriction Controller
    this.Controller.subscribe(controller => {
      this.title = controller.Title;
      this.message = controller.Message;
      this.buttonTitle = controller.ButtonTitle;
      this.buttonAction = controller.ButtonAction;
    });
  }

  Close(){
    this.overlayService.hideOverlay();
  }

  GoToURL() {
    window.location.href = "/" + this.buttonAction;
  }
}
