import { Component, Input, OnInit, OnDestroy } from '@angular/core';

@Component({
  selector: 'app-clock',
  templateUrl: './clock.component.html',
  styleUrls: ['./clock.component.scss']
})
export class ClockComponent implements OnInit, OnDestroy {
  @Input() clock: Date = new Date();
  @Input() duration?: number; // Optional duration input
  @Input() clockContainerStyle: any;
  @Input() timerStyle: any;
  @Input() timeUnitStyle: any;
  @Input() valueStyle: any;
  @Input() labelStyle: any;
  @Input() useLongLabels: boolean = false; // New input for label format

  days: number = 0;
  hours: number = 0;
  minutes: number = 0;
  seconds: number = 0;
  timer: any;

  ngOnInit() {
    this.startTimer();
  }

  ngOnDestroy() {
    this.clearTimer();
  }

  startTimer() {
    const endDate = new Date(this.clock);

    // If duration is provided, add it to the end date
    if (this.duration) {
      endDate.setDate(endDate.getDate() + this.duration);
    }

    this.timer = setInterval(() => {
      const now = new Date();
      const difference = endDate.getTime() - now.getTime();

      if (difference > 0) {
        this.days = Math.floor(difference / (1000 * 60 * 60 * 24));
        this.hours = Math.floor((difference % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        this.minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
        this.seconds = Math.floor((difference % (1000 * 60)) / 1000);
      } else {
        this.clearTimer();
      }
    }, 1000);
  }

  clearTimer() {
    if (this.timer) {
      clearInterval(this.timer);
    }
  }

  getDayLabel(): string {
    return this.days === 1 ? 'Day' : 'Days';
  }

  getHourLabel(): string {
    return this.hours === 1 ? 'Hour' : 'Hours';
  }

  getMinuteLabel(): string {
    return this.minutes === 1 ? 'Minute' : 'Minutes';
  }

  getSecondLabel(): string {
    return this.seconds === 1 ? 'Second' : 'Seconds';
  }
}