import { Component, Input, OnInit } from '@angular/core';
import { trigger, state, style, animate, transition } from '@angular/animations';
import { ErrorHandlingService } from './ErrorHandling_Service';
import { Router } from '@angular/router';

interface ErrorData {
  Success: boolean;
  Message: string;
  Token?: any;
}

@Component({
  selector: 'error',
  templateUrl: './error.component.html',
  styleUrls: ['./error.component.scss'],
  animations: [
    trigger('slideInOut', [
      state('in', style({ transform: 'translateX(0)', opacity: 1 })),
      state('hidden', style({ transform: 'translateX(100%)', opacity: 0 })),
      transition(':enter', [
        style({ transform: 'translateX(-100%)', opacity: 0 }),
        animate('100ms ease-in', style({ transform: 'translateX(50%)', opacity: 1 })),
        animate('200ms ease-out', style({ transform: 'translateX(0)' }))
      ]),
      transition('in => hidden', [
        animate('300ms ease-out', style({ transform: 'translateX(100%)', opacity: 0 }))
      ])
    ])
  ]
})
export class ErrorComponent implements OnInit {
  @Input() ErrorData: ErrorData | null = null;
  showError = false;
  animationState = 'hidden';

  constructor(
    private errorService: ErrorHandlingService,
    private router: Router
  ) { }

  ngOnInit() {

    this.errorService.error$.subscribe((error) => {
      const currentRoute = this.router.url;

      if (error && error.Message) {
        this.showError = true;
        this.ErrorData = error;
        this.animationState = 'in';
        const timeoutDuration = this.calculateTimeoutDuration(error.Message);
        window.scrollTo(0, 0);

        setTimeout(() => {
          this.animationState = 'hidden';
          setTimeout(() => {
            this.showError = false;
          }, 300); // Match the animation duration
          this.errorService.clearError();
        }, timeoutDuration);
      }
    });
  }

  calculateTimeoutDuration(message: string): number {
    const baseDuration = 1000; // Base duration in milliseconds (1 second)
    const additionalDuration = Math.ceil(message.length / 10) * 1000; // Additional duration based on message length
    return baseDuration + additionalDuration;
  }

  closeError() {
    this.animationState = 'hidden';
    setTimeout(() => {
      this.showError = false;
      this.errorService.clearError();
    }, 300); // Match the animation duration
  }
}