
import { Component, OnInit } from '@angular/core';

// Api Call
import { KeysComponent } from '../KEYS';

// Form Functions
import { AbstractControl, FormGroup, Validators, FormBuilder } from '@angular/forms';
import { FormService } from '../Functions_Forms';

// User Session
import { IndexedDBService } from '../Functions_USession';

// ION VARS
import { eyeOutline,eyeOffOutline, logInOutline} from 'ionicons/icons';
import { take } from 'rxjs';


@Component({
  selector: 'app-contactus',
  templateUrl: './contact-us.component.html',
  styleUrls: ['./contact-us.component.scss']
})


export class ContactUsComponent implements OnInit {
  User!: any;
  contactForm: FormGroup;
  constructor(private formBuilder: FormBuilder, private Keys: KeysComponent, public FormService: FormService,
    private userService: IndexedDBService
  ) {
    this.contactForm = this.formBuilder.group({
      name: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(25), Validators.pattern('^[a-zA-Z ]*$')]],
      emailTO: ['', [Validators.required, Validators.email]],
      message: ['', [Validators.required, Validators.maxLength(200), Validators.minLength(3)]],
    });
  }
  ngOnInit() {
      this.userService.USERDATA$.pipe(take(1)).subscribe((data: any) => {
        this.User = data;
      })

      //changes the email input to the inputed one
    this.contactForm.patchValue({
      emailTO: this.User.Email
    });
    }
  // Submit Form
  onSubmit(){
    this.FormService.onSubmit(this.contactForm, this.User.CALL.Send_E_Mail); 
  }
}