import { Component, Input } from '@angular/core';

// Api Call
import { KeysComponent } from '../../../KEYS';

// Form Functions
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { FormService } from '../../../Functions_Forms';

// ION VARS
import { mailOutline } from 'ionicons/icons';
import { IndexedDBService } from '../../../Functions_USession';
import { take } from 'rxjs/operators';

@Component({
  selector: 'login-passreset',
  templateUrl: './passreset.component.html',
  styleUrls: ['./passreset.component.scss']
})
export class PassresetComponent {
  //icons
  email_outline = mailOutline;

  //is this necessary?
  @Input() Email: string = '';

  // Login Constructor
  PassResetForm: FormGroup;
  constructor(
    private formBuilder: FormBuilder,
    private Keys: KeysComponent,
    public FormService: FormService,
    public userService: IndexedDBService
  ) {

    this.PassResetForm = this.formBuilder.group({
      website: [''], // honeypot
      usepass: ['', [Validators.required, Validators.email, Validators.minLength(7), Validators.maxLength(50)]],
    });
  }
  
  User!: any;
  ngOnInit(): void {
    this.userService.USERDATA$.pipe(take(1)).subscribe((data: any) => {
      this.User = data;
    })
  }

  // Submit Form
  onSubmit() {
    this.FormService.onSubmit(this.PassResetForm, this.User.CALL.Pass_Reset);
  }


}
