import { Injectable, OnDestroy } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { environment } from '../environment';
import { ApiService } from '../../Functions_API';
import { EC_Functions } from '../EC_Functions';
import { PaymentMethod, Stripe, StripeCardElement } from '@stripe/stripe-js';
import { Observable } from 'rxjs';
import { StripeService } from './stripe.service';
import { PackagesInterface } from '../EC_Packages';
import { ServicesInterface } from '../EC_Services';

export interface PaymentIntentResponse {
  clientSecret: string;
}

@Injectable({
  providedIn: 'root',
})
export class PaymentService {
  private stripe: Stripe | null = null;

  constructor(
    private http: HttpClient,
    private API: ApiService,
    private ECF: EC_Functions,
    private stripeService: StripeService
  ) {}

  private async getStripe(): Promise<Stripe | null> {
    if (!this.stripe) {
      this.stripe = await this.stripeService.getStripe();
    }
    return this.stripe;
  }

  createPaymentIntent(paymentMethod: PaymentMethod, customer: any): Observable<any> {
    const cart = this.ECF.getCartt();
    const total = this.ECF.getcartTotal(cart);
    
    const details = {
      "CALL": "eC0mm3rce",
      "amount": total * 100,
      "currency": "usd",
      "payment_method": paymentMethod.id,
      "customer": customer
    };
    return this.API.post(details, "eC0mm3rce");
  }

  async createPaymentMethod(card: StripeCardElement, customerID: string, billingDetails: {address: {city: string, line1: string, postal_code: string, state: string}, email: string, name: string}): Promise<PaymentMethod | undefined> {
    const stripe = await this.getStripe();
    if (!stripe || !card) {
      console.error('Card information is incomplete or invalid.');
      return undefined;
    }

    try {
      const { paymentMethod, error } = await stripe.createPaymentMethod({
        type: 'card',
        card: card,
        billing_details: billingDetails
      });

      if (error) {
        console.error('Stripe createPaymentMethod error:', error);
        return undefined;
      } else if (paymentMethod) {

        //Set customer ID.
        paymentMethod.customer = customerID;
        return paymentMethod;
      }
      
      return undefined;
    } catch (error) {
      console.error('Error creating payment method:', error);
      return undefined;
    }
  }

  async confirmPayment(clientSecret: string, paymentMethod: PaymentMethod) {
    const stripe = await this.getStripe();
    if (!stripe) {
      console.error('Stripe instance is not available.');
      return;
    }

    try {
      const { paymentIntent, error } = await stripe.confirmCardPayment(clientSecret, {
        payment_method: paymentMethod.id,
      });

      if (error) {
        console.error('Error confirming payment:', error);
      } else if (paymentIntent) {
        //console.log('PaymentIntent confirmed:', paymentIntent);

        // Send payment confirmation to your backend
        const paymentDetails = { "CALL": "eC0mm3rce", "paymentIntentId": paymentIntent.id, "paymentMethodId": paymentMethod.id };
        const response = await <any>this.API.post(paymentIntent.id, "c0nf1rm");

        const result = await response.json();
        //console.log('Backend response:', result);

        if (result.status === 'succeeded') {
          // Handle successful payment here
          //console.log('Payment succeeded');
        } else {
          // Handle other payment statuses here
          //console.log('Payment not completed:', result.status);
        }
      }
    } catch (error) {
      //console.error('Error confirming payment:', error);
    }
  }
  cleanup() {
    this.stripe = null;
    this.stripeService.cleanup();
  }
}
