import { AfterViewInit, Component, Input, OnDestroy, OnInit, Renderer2 } from '@angular/core';
import { IndexedDBService } from '../../Functions_USession';
import { Subscription } from 'rxjs';
import { ShareprofileService } from '../../Profile/shareprofile/shareprofile.service';
import { Router,NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { chatbubblesOutline, appsOutline } from 'ionicons/icons';
import {sRouteKey} from '../../Settings/settings.routes';
import {lRouteKey} from '../../login/Login/login.routes';

interface DropdownOption {
  Icon: string;
  Title: string;
  func: () => void;
}

@Component({
  selector: 'hub-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss']
})
export class HeaderComponent implements OnInit, OnDestroy {
  constructor(
    private router: Router,
    private userService: IndexedDBService,
    private renderer: Renderer2
  ) {
    this.userService.isLoggedIn().then(isLoggedIn => {
      this.isLoggedIn = isLoggedIn;
    });
  }

  // vars ///////////////////////////////////////////////////////////
  User: any;
  isLoggedIn!: boolean; 
  private userSubscription!: Subscription;
  logo!: string; 
  title!: string;
  private ignoreClickOutside: boolean = false; // Flag to ignore clicks outside temporarily
  
  
  @Input() Show: boolean = true; // to hide or show the entire element 
  UserName: string | null = null;
  appsOutline = appsOutline; // ion icons
  //for routing
  login = lRouteKey;
  setting = sRouteKey;
  SettingDropdownOptions: any;
  

  ngOnInit() {
    this.userSubscription = this.userService.USERDATA$.subscribe(
      (userData) => {
        this.User = userData;
        let SettingCheck = userData ? userData.SETTINGS : null;
        if(SettingCheck){
          this.logo = userData.CONFIG.LOGO;
          this.title = userData.CONFIG.BUSName;
          let Nav = userData.SETTINGS.UserNav ?? ['','Unavailable',''];
          this.SettingDropdownOptions = this.generateNavigationArray(Nav);  
        }
      }
    );

    this.router.events.pipe(
      filter(event => event instanceof NavigationEnd)
    ).subscribe(() => {
      this.userService.isLoggedIn().then(isLoggedIn => {
        this.isLoggedIn = isLoggedIn;
      });
    });

     // Add event listener for clicks outside the dropdown menu
     this.renderer.listen('document', 'click', this.handleClickOutside.bind(this));
 
  }

  ngOnDestroy() {
    // Unsubscribe to prevent memory leaks
    if (this.userSubscription) {
      this.userSubscription.unsubscribe();
    }
  }

  toggleDropdown() {
    const dropdownMenu = document.getElementById('dropdownMenu');
    if (dropdownMenu) {
      dropdownMenu.style.display = dropdownMenu.style.display === 'block' ? 'none' : 'block';
      this.ignoreClickOutside = true; // Ignore the next click outside
      setTimeout(() => this.ignoreClickOutside = false, 0); // Reset the flag after the current event loop
    }
  }

  handleClickOutside(event: Event) {
    if (this.ignoreClickOutside) {
      return; // Ignore this click
    }
    const dropdownMenu = document.getElementById('dropdownMenu');
    if (dropdownMenu && dropdownMenu.style.display === 'block' && !dropdownMenu.contains(event.target as Node)) {
      this.toggleDropdown();
    }
  }

  
  generateNavigationArray(items: string[]): DropdownOption[] {
    return items.map(item => {
      return {
        Icon: item[0],
        Title: item[1],
        func: () => {
          this.router.navigate([`/${item[2].toLowerCase()}`]);
          this.toggleDropdown();
        }
      };
    });
  }

  // Links ///////////////////////////////////////////////////////////
  public home() {
    this.router.navigate(['/']);
  }
  Login_() {
    this.router.navigate(['/'+this.login.login]);
  }
}