import { Component, Input } from '@angular/core';
import { ShareprofileService } from './shareprofile.service';
import { shareSocialOutline } from 'ionicons/icons';

@Component({
  selector: 'profile-shareprofile',
  templateUrl: './shareprofile.component.html',
  styleUrls: ['./shareprofile.component.scss']
})
export class ShareprofileComponent {
  @Input() dis_name: string | null = null;
  constructor(private ShareProfile: ShareprofileService) { }

  Share = shareSocialOutline;

  public share_() {
    if(!this.dis_name) {
      this.ShareProfile.share_();
    } else {
      this.ShareProfile.share_(this.dis_name);
    }
  }
}
