import { Component, Input, OnInit } from '@angular/core';
import { IndexedDBService } from '../../Functions_USession';
import { skip, Subscription, take } from 'rxjs';

interface InvoiceInfo {
  name: string;
  address: {
    city: string,
    line1: string,
    country: string,
    line2: string,
    postal_code: string,
    state: string
  };
  email: string;
  payment_method: string;
  last4: string;
  cardBrand: string;
}

@Component({
  selector: 'lib-invoice',
  templateUrl: './invoice.component.html',
  styleUrls: ['./invoice.component.scss']
})
export class InvoiceComponent implements OnInit {
  @Input() data!: InvoiceInfo;
  billingAddress: { key: string, value: string }[] = [];

    constructor(
        private indexdb: IndexedDBService
    ){}
    
    ngOnInit() {
    if (this.data && this.data.address) {
      this.billingAddress = Object.entries(this.data.address)
        .filter(([key, value]) => value !== null && value !== undefined && value !== '')
        .map(([key, value]) => ({ key, value }));
    }
  }

    home(){
      //needs to reload the page to get rid of stripe Iframe elements
        window.location.href = '/';
    }
}
