import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { ApiService } from '../Functions_API'; // API

import { DomSanitizer, SafeHtml } from '@angular/platform-browser'; // Sanitize

@Component({
  selector: 'legal-Paperwork',
  templateUrl: './legal.component.html',
  styleUrls: ['./legal.component.scss']
})
export class LegalComponent {
  HTML_Output: any; // html from server
  sanitizedHtml!: SafeHtml;
  Content: 'policies' | 'terms' | 'datarequest' | 'storepolicies' = 'policies';

  constructor(
    private router: ActivatedRoute,
    private HTTPCall: ApiService,
    private sanitizer: DomSanitizer
  ) {
    
  }

  ngOnInit() {
    this.router.url.subscribe(url => {
      const urlString = url.map(segment => segment.toString()).join('/');
      this.fetchContent(urlString);
    });
    
  }


  fetchContent(url: string): void {

    this.HTTPCall.TakeAction({ CALL: url, Type: null }).subscribe((response: any) => {
      if (response.Success) {
        this.HTML_Output = response.Token as string;
        this.sanitizedHtml = this.sanitizer.bypassSecurityTrustHtml(this.HTML_Output);
      } else {
        this.HTML_Output = response.Message as string;
        this.sanitizedHtml = this.sanitizer.bypassSecurityTrustHtml(this.HTML_Output);
      }
    });
  }
}