import { Component, OnInit } from '@angular/core';
import { EC_Functions } from '../../EC_Functions';
import { Observable } from 'rxjs';

@Component({
  selector: 'ec-sidecart',
  templateUrl: './sidecart.component.html',
  styleUrls: ['./sidecart.component.scss']
})
export class SidecartComponent implements OnInit{
  constructor(private EC_Func: EC_Functions) { 
    this.Cart = this.EC_Func.getCartt();
    this.Total = this.EC_Func.getcartTotal(this.Cart);
  }

  // Control Side Nav Cart
  ShowCart: boolean = false;
  Cart_Display() {
    this.ShowCart = !this.ShowCart;
  }
  // Vars
  Total: number = 0;
  Cart: any[];
    ngOnInit(): void {
      // Update Cart and Associated Vars 
      this.EC_Func.Cart.subscribe(items => {
        this.Cart = items;
        this.Total = this.EC_Func.getcartTotal(this.Cart);
      });
    }

  trackByFn(index: number, item: any): number {
    return item.ID; // or any unique property of the item
  }

}
