import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

export interface Controller {
  Title: string;
  Message: string;
  ButtonTitle: string;
  ButtonAction: string;
}

@Injectable({
  providedIn: 'root'
})
export class AccessRestrictOverlayService {
  private isVisibleSubject = new BehaviorSubject<boolean>(false);
  isVisible$ = this.isVisibleSubject.asObservable();

  private ControllerSubject = new BehaviorSubject<Controller>({Title: 'Access Restricted', Message: 'You do not have access to this page',ButtonTitle: 'Request Access',ButtonAction: ''});
  Controller$ = this.ControllerSubject.asObservable();


  updateController(controller: Controller) {
    this.ControllerSubject.next(controller);
  }

  showOverlay() {
    this.isVisibleSubject.next(true);
  }

  hideOverlay() {
    this.isVisibleSubject.next(false);
  }
}