import { Component } from '@angular/core';

// User Session
import { IndexedDBService } from '../Functions_USession';

// View
import { ActivatedRoute } from '@angular/router';
import { sRouteKey } from './settings.routes';
import { lRouteKey } from '../login/Login/login.routes';
import { ROUTE_CONFIG } from '../GLOBALS.service';
import { Router } from '@angular/router';

// Animations
import { trigger, state, style, animate, transition } from '@angular/animations'

// Icons
import { arrowForwardOutline, arrowBackOutline, star } from 'ionicons/icons';
import { take } from 'rxjs';


@Component({
  selector: 'app-settings',
  templateUrl: './settings.component.html',
  styleUrls: ['./settings.component.scss'],
  animations: [
    trigger('slideAnimation', [
      state('settings', style({ transform: 'translateX(0)' })),
      state('profile', style({ transform: 'translateX(100%)' })),
      state('account', style({ transform: 'translateX(200%)' })),
      transition('settings => profile', animate('500ms ease-in-out')),
      transition('profile => account', animate('500ms ease-in-out')),
      transition('account => profile', animate('500ms ease-in-out')),
      transition('profile => settings', animate('500ms ease-in-out')),
      transition('settings => account', animate('500ms ease-in-out')),
      transition('account => settings', animate('500ms ease-in-out'))
    ])
  ]
})

export class SettingsComponent {
  // Define Routes
  routeKey = sRouteKey;
  routeKeyLogin = lRouteKey
  routeView = this.route.snapshot.url[0] ? this.route.snapshot.url[0]['path'] : ''; // controls view of the page
  // To handle additional Settings 
  additionalSettings: any = ROUTE_CONFIG.filter(route =>route.component === SettingsComponent && !(route.path in this.routeKey));
  User!: Promise<any>;
  constructor(
    private USessionData: IndexedDBService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

  // User Info Grab
  ngOnInit() {
    //this.User = await this.USessionData.getData();
  }

  //ion icons
  arrowleft = arrowForwardOutline;
  arrowright = arrowBackOutline;
  star = star;

  setViewState(view: string) {
    if (view) {
      this.router.navigate(['/' + view]);
    }
  }
  


}
