import { Component, Input } from '@angular/core';
import { Router, ActivatedRoute } from '@angular/router';

// ECommerce Packages
import { EC_Functions } from '../../EC_Functions';
import { PackagesInterface } from '../../EC_Packages';
import { ServicesInterface } from '../../EC_Services';
import { from } from 'rxjs';

@Component({
  selector: 'ec-itemsdisplay',
  templateUrl: './itemsdisplay.component.html',
  styleUrls: ['./itemsdisplay.component.scss']
})
export class ItemsdisplayComponent {
  constructor(public EC_Func: EC_Functions, public router: Router) {
    this.Cart = this.EC_Func.getCartt();
    this.Total = this.EC_Func.getcartTotal(this.Cart);
  }

  // Vars
  Total: number = 0;
  Cart: any[];
  ngOnInit(): void {
    // Update Cart and Associated Vars 
    this.EC_Func.Cart.subscribe(items => {
      this.Cart = items;
      this.Total = this.EC_Func.getcartTotal(this.Cart);
    });
  }

  trackByFn(index: number, item: any): number {
    return item.id; // or any unique property of the item
  }

  Price_OutputFilter(Input: any): string {
    return Input[0].Price.toLocaleString('en-US', { style: 'currency', currency: 'USD' }) + " / " + (Input[0].Length ?? " ");
  }

  Remove(item: (PackagesInterface | ServicesInterface)){
    this.EC_Func.UpdateCart(item, "clear");
  }
  Clear(){
    this.EC_Func.ClearCart();
  }
//side cart --> cart --> checkout
  CheckoutOrView(){
    if (this.router.url === '/cart'){
        this.EC_Func.Checkout();
    }
    else {
        this.EC_Func.ViewCart();
    }
   
  }
  //to show total
  // getTotal() {
  //   return Object.values(this.Cart).reduce((total, item: any) => {
  //     const price = item.Tiers[0].Price;  // Assuming you're using the first tier for the price
  //     const quantity = item.Quantity ?? 1; // Default to 1 if no quantity is provided
  //     return total + price * quantity;
  //   }, 0);
  // }

  Checkout = this.EC_Func.Checkout;
  showCheckout = this.EC_Func.Checkout;
  isCartEmpty = this.EC_Func.isCartEmpty;
  ClearCart = this.EC_Func.ClearCart;
  getCartt = this.EC_Func.getCartt;
  getcartTotal = this.EC_Func.getcartTotal;


}
