import { Component, ElementRef, Input, OnInit, OnDestroy, ViewChild } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { IndexedDBService } from '../../Functions_USession';
import { ErrorHandlingService } from '../../Components/Error/ErrorHandling_Service';
import { catchError, Subscription, BehaviorSubject, of, finalize, take } from 'rxjs';
import { cameraReverseOutline } from 'ionicons/icons';
import { KeysComponent } from '../../KEYS';
import { FormGroup } from '@angular/forms';
import { Router } from '@angular/router';
// import ngsrc fromr ngimgsrc 
import { NgOptimizedImage } from "@angular/common";



@Component({
  selector: 'profilePhoto',
  templateUrl: './profile-photo.component.html',
  styleUrls: ['./profile-photo.component.scss']
})
export class ProfilePhotoComponent implements OnInit, OnDestroy {
  @Input() Type: 'view' | 'edit' = 'view';
  @Input() style: { [key: string]: string } = {};
  @Input() PicUrl!: string;
  @Input() AllowGoToProfile: boolean = false;

  User: any = {};
  Domain!: string;
  photoFailSafe = '/assets/Stockphoto.png';
  photoStyle = { 'background-image': '' };

  photoUploadIcon = cameraReverseOutline;
  isLoading$ = new BehaviorSubject<boolean>(false);
  profilePhoto$ = new BehaviorSubject<string>('/assets/Stockphoto.png');

  private readonly allowedFileTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif'];
  AllowedFileTypes = this.allowedFileTypes.join(', ');
  private readonly maxSizeInBytes = 30 * 1024 * 1024; // 30 MB
  private userSubscription?: Subscription;

  @ViewChild('fileInput', { static: false }) fileInput?: ElementRef<HTMLInputElement>;

  uploadForm!: FormGroup;
  Debug!: boolean;
  API!: string;
  constructor(
    private indexedDBService: IndexedDBService,
    private errorHandlingService: ErrorHandlingService,
    private Keys: KeysComponent,
    private http: HttpClient,
    private Router: Router
  ) {
  }

  ngOnInit(): void {
    this.userSubscription = this.indexedDBService.USERDATA$.pipe(take(1)).subscribe(
      userData => {
        this.User = userData;
        let SettingCheck = userData ? userData.CONFIG : null;
        if (SettingCheck) {
          this.Domain = userData.CONFIG.URL;
          this.API = userData.CONFIG.URL + userData.CONFIG.API;
          this.Debug = userData.CONFIG.DEBUG;
        }

        if (this.PicUrl) {
          // this.profilePhoto$.next(this.PicUrl);
          // this.getProfilePhotoStyle();
          // console.log(this.profilePhoto$.value);
          this.renderProfilePhoto(this.PicUrl);
        } else {
          if (userData?.pictures) {
            this.renderProfilePhoto(userData.pictures);
          }
        }
      }
    );
  }

  ngOnDestroy(): void {
    this.userSubscription?.unsubscribe();
  }

  onFileSelected(event: Event): void {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (!file) {
      this.errorHandlingService.setError({ Success: false, Message: 'No file selected.' });
      return;
    }
    if (!this.isValidFile(file)) return;

    this.uploadPhoto(file);
  }

  getProfilePhoto(): void {
    this.renderProfilePhoto();
  }

  PhotoLink: string = ';'
  getProfilePhotoStyle(): void {
    let link = this.profilePhoto$.value;
    this.photoStyle = {
      'background-image': `url(${this.profilePhoto$.value})`,
      ...this.style
    };
    this.PhotoLink = link;
  }

  openFileInput() {
    this.fileInput?.nativeElement.click();
  }

  private isValidFile(file: File): boolean {
    if (!this.allowedFileTypes.includes(file.type)) {
      this.errorHandlingService.setError({
        Success: false,
        Message: `Invalid file format. Please select a ${this.allowedFileTypes.join(', ')} image.`
      });
      return false;
    }

    if (file.size > this.maxSizeInBytes) {
      this.errorHandlingService.setError({
        Success: false,
        Message: `File size exceeds ${this.maxSizeInBytes / 1024 / 1024}MB. Please select a smaller file.`
      });
      return false;
    }

    return true;
  }

  private uploadPhoto(file: File): void {

    this.isLoading$.next(true);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('Type', 'ProfilePhoto');
    formData.append('current', this.profilePhoto$.value);
    formData.append('CALL', this.Keys.ProPhoto);
    formData.append('Sub', this.User.Ky);

    if (this.Debug === true) {
      console.log(Array.from((formData as any).entries()));
    }

    this.http.post<any>(this.API, formData).pipe(
      catchError((error: HttpErrorResponse) => {
        this.errorHandlingService.setError({ Success: false, Message: error.message });
        return of(null);
      }),
      finalize(() => this.isLoading$.next(false))
    ).subscribe(response => {
      if (this.Debug === true) {
        console.log(response);
      }
      if (response.Success) {
        this.indexedDBService.updateSession({ pictures: response.Token });
        this.errorHandlingService.setError(response.Message);
        setTimeout(() => {
          //this.Router.navigate(['/profile']);
          window.location.reload();
        }, 2000);
      } else {
        this.errorHandlingService.setError(response.Message);
      }
    });
  }

  private async renderProfilePhoto(url?: string): Promise<void> {
    if (!url) { url = '/assets/Stockphoto.png' } // fallback image

    // FORCE DOMAIN LINK TO URL
    url = this.Domain + url;
    try {
      await this.http.head(url).toPromise();
      let link = `${url}?t=${new Date().getTime()}`;
      await this.profilePhoto$.next(link);
      this.getProfilePhotoStyle();
    } catch {
      this.profilePhoto$.next(this.photoFailSafe);
      this.errorHandlingService.setError({ Success: false, Message: 'Failed to load profile photo- error updating' }); // frontend error message
      this.getProfilePhotoStyle();
    }
  }

  public profile() {
    if (this.Type !== 'edit' && this.AllowGoToProfile === true) {
      this.Router.navigate(['/profile']);
    }

  }
}