import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

@Injectable({
    providedIn: 'root'
})


export class SplashHandlingService {
    private _splash$ = new BehaviorSubject<boolean>(false);
    splash$: Observable<boolean> = this._splash$.asObservable();

    setSplash() {
        this._splash$.next(true);
    }

    unsetSplashPage() {
        this._splash$.next(false); // delay is set on individual pathway API Fumnc
    }

}
