import { Component, OnInit, Input, OnDestroy } from '@angular/core';

// Api Call
import { KeysComponent } from '../../../KEYS';

// Form Functions
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { FormService } from '../../../Functions_Forms';

// User Session
// import { IndexedDBService } from '../../Functions_USession';

// ION VARS
import { eyeOutline,eyeOffOutline, logInOutline} from 'ionicons/icons';

// Routing
import { lRouteKey } from '../login.routes';
import { Router } from '@angular/router';
import { IndexedDBService } from '../../../Functions_USession';
import { take } from 'rxjs/operators';

@Component({
  selector: 'login-form',
  templateUrl: './loginform.component.html',
  styleUrls: ['./loginform.component.scss']
})


export class LoginformComponent implements OnInit, OnDestroy {
  // Password show feature 
  ShowPassword = false; 
  togglePasswordVisibility() {
    this.ShowPassword = !this.ShowPassword;
  }

  eye_outline = eyeOutline; // icon
  eye_off_outline = eyeOffOutline;
  log_in_outline = logInOutline;

  // Login Constructor
  LoginForm: FormGroup;
  Remember: any = false;
  //input email
  @Input() defaultEmail: string = '';
  User!: any;

  //view
  view = lRouteKey;

  constructor(
    private formBuilder: FormBuilder, 
    private Keys: KeysComponent, 
    public FormService: FormService,
    public router: Router,
    private userService: IndexedDBService
  ) {
    this.LoginForm = this.formBuilder.group({
      website: [''], // honeypot
      usemal: ['', [Validators.required, Validators.email, Validators.minLength(7), Validators.maxLength(50)]],
      pqwrd: ['', [Validators.required]],
      rememberme: [false]
    });
  }
  private userSubscription: any;

  ngOnInit() {
    this.userSubscription = this.userService.USERDATA$.subscribe((data: any) => {
      this.User = data;
    })

    //changes the email input to the inputed one
    this.LoginForm.patchValue({
      usemal: this.defaultEmail
    });
  }
  // Submit Form
  HideLogin: boolean = false;
  async onSubmit(){
    this.HideLogin = true;
    await this.FormService.onSubmit(this.LoginForm, this.User.CALL.Login); // first for login
    this.HideLogin = false;
  }
    
  ngOnDestroy() {
    this.userSubscription.unsubscribe();
  }
}

