import { Component } from '@angular/core';
// Routing
import {lRouteKey} from '../login.routes';
import { Router } from '@angular/router';

// Api Call
import { KeysComponent } from '../../../KEYS';

// Form Functions
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { FormService } from '../../../Functions_Forms';
import { firstValueFrom } from 'rxjs';

// ION VARS
import {logInOutline} from 'ionicons/icons';

@Component({
  selector: 'login-pop-up',
  templateUrl: './login-pop-up.component.html',
  styleUrls: ['./login-pop-up.component.scss']
})
export class LoginPopUpComponent {
  //ion icons
  log_in_outline = logInOutline;
  //switch between email form, login form, and signup form
  ErrorTrack: {} | null = null;

  RegForm: FormGroup;
  //login or create acount
  loginTrue: boolean | null;

  view = lRouteKey;
  
  constructor(private formBuilder: FormBuilder, private Keys: KeysComponent, private router: Router,public FormService: FormService,) { 
    this.loginTrue = null;
    this.RegForm = this.formBuilder.group({
      website: [''], // honeypot
      nusemal: ['', [Validators.required, Validators.email, Validators.minLength(7), Validators.maxLength(85)]],
      disName: ['', [Validators.minLength(3), Validators.maxLength(50), Validators.required]]
    });
  }

  async CheckExi(ControlName: string, Type: string){
    // run validation
    
    this.ErrorTrack = await firstValueFrom(this.FormService.CheckEmail(this.RegForm,ControlName));
    if(this.ErrorTrack){
      // this.navigationService.navigateTo(this.view.login);
      this.loginTrue = true;
    } else {
      // this.navigationService.navigateTo(this.view.createAccount);
      this.loginTrue = false;
    }
  }
  openPrivacy(){
    //not implemented
    this.router.navigate(['/policies']);
  }
  get defaultEmail(): string {;
    return this.RegForm.get('nusemal')?.value ?? '';
  }
}
