import { Component } from '@angular/core';

// Routing
import {lRouteKey} from '../login.routes';
import { Router } from '@angular/router';


// User Session
import { IndexedDBService } from '../../../Functions_USession';

@Component({
  selector: 'login-logout',
  templateUrl: './logout.component.html',
  styleUrls: ['./logout.component.scss']
})
export class LogoutComponent {
  //view
  view = lRouteKey;

    constructor(
      private router: Router, 
      private User: IndexedDBService
    ) { }

     public async logout(){
      await this.User.logoutSession();
      this.router.navigate(["/"+this.view.login.path]); // refresh the page
    }
}
