import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { IndexedDBService } from '../../Functions_USession';
import { home, peopleOutline, informationCircleOutline, settingsOutline, chatbubblesOutline } from 'ionicons/icons';
import { Subscription } from 'rxjs';
import { filter } from 'rxjs/operators';

@Component({
  selector: 'hub-footer',
  templateUrl: './footer.component.html',
  styleUrls: ['./footer.component.scss']
})
export class FooterComponent implements OnInit, OnDestroy {
  isLoggedIn!: boolean;
  @Input() Show: boolean = true; // to hide or show the entire element

  // icons //////////////////////
  home = home;
  meet = peopleOutline;
  guide = informationCircleOutline;
  settings = settingsOutline;
  chat = chatbubblesOutline;
  @Input() buttons: Array<{
    icon: string;
    label: string;
    route: string;
    active: boolean;
  }> = [  
    {
      "icon": this.meet,
      "label": "Connect",
      "route": "/match",
      "active": false
    },
    {
      "icon": this.guide,
      "label": "Guide",
      "route": "/guide",
      "active": false
    },
    {
      "icon": this.chat,
      "label": "Messages",
      "route": "/messages",
      "active": false
    }
  ];

  userSubscription!: Subscription;
  routerSubscription!: Subscription;

  constructor(
    public View: Router,
    private router: Router,
    private userService: IndexedDBService,
  ) {}

  ngOnInit() {
    this.userService.isLoggedIn().then(isLoggedIn => {
      this.isLoggedIn = isLoggedIn;
      if (this.isLoggedIn) {
        /*
          REMOVED for now - gave trouble loading footer - too slow 
        */
        // this.userSubscription = this.userService.USERDATA$.subscribe(
        //   (userData) => {
        //     let SettingCheck = userData ? userData.CONFIG : null;
        //     //this.buttons = userData.SETTINGS.UserNav_Footer;
        //     // Set the initial active button based on the current route
        //     this.updateActiveButton(this.router.url.toLowerCase());
        //   }
        // );
      }
    });


    // this.userSubscription = this.userService.USERDATA$.subscribe(
    //   (userData) => {
    //     if (userData && userData.SETTINGS) {
    //       this.buttons = [...userData.SETTINGS.UserNav_Footer]; // Create a new array reference
    //       this.updateActiveButton(this.router.url.toLowerCase());
    //     }
    //   }
    // );

    this.routerSubscription = this.router.events.pipe(
      filter(event => event instanceof NavigationEnd)
    ).subscribe((event) => {
      const navEndEvent = event as NavigationEnd;
      this.userService.isLoggedIn().then(isLoggedIn => {
        this.isLoggedIn = isLoggedIn;
        this.updateActiveButton(navEndEvent.urlAfterRedirects.toLowerCase());
      });
    });
  }

  ngOnDestroy() {
    // Unsubscribe to prevent memory leaks
    if (this.userSubscription) {
      this.userSubscription.unsubscribe();
    }
    if (this.routerSubscription) {
      this.routerSubscription.unsubscribe();
    }
  }

  // Method to handle routing
  public route(destination: string) {
    this.updateActiveButton(destination.toLowerCase());
    this.router.navigate(['/' + destination]);
  }

  private updateActiveButton(destination: string) {
    this.buttons = this.buttons.map(button => ({
      ...button,
      active: button.route === destination
    }));
  }

  trackByFunction(index: number, button: any): string {
    return button.route;
  }
}