import { Component } from '@angular/core';
import { Packages, NavList } from '../EC_Packages';
import { Services, WebsiteAdvancedServices } from '../EC_Services';
import { EC_Functions } from '../EC_Functions';
import {eRouteKey} from '../ecommerce.routes';
import { Router } from '@angular/router';

@Component({
  selector: 'ec-shop-view',
  templateUrl: './shop-view.component.html',
  styleUrls: ['./shop-view.component.scss']
})

export class ShopViewComponent {
  //view
  view = eRouteKey;

  constructor(private EC_Func: EC_Functions, private router: Router) {}
  
  // E-Commerce Setup
  NavItems = NavList; // organize by Type
  AllAvailable = this.EC_Func.ConstructStoreItems();
  CustomServices = WebsiteAdvancedServices;

  // Functions
  addToCart(item: any){
    if(item && item.Tiers){
      let priceKeys = Object.keys(item.Tiers).length;
      //If the product's price has more than 1 key, it has multiple tiers.
      if(priceKeys > 1){
        this.EC_Func.ViewProductInfo(item.ID)
      } else {
      this.EC_Func.UpdateCart(item);
      }
  }
    
  }

  ViewProductInfo = this.EC_Func.ViewProductInfo;
  filterServices(Category: string) {
    return this.AllAvailable.filter(s => s.Type === Category);
  }

  // Product
  projectRequest() {
    // redirect to project request page 
    // in the future create contact.route
    this.router.navigate(['/contact']);
  }

}


